subnets.description:
List of subnet calculation tasks to perform using subnetcalc flags and arguments.
items field defines the structure of each item in this list.
items: {
  address: {
    type: string,
    default: "127.0.0.1",
    description: "The IP address or hostname to calculate."
  },
  prefix: {
    type: "string",
    default: "24",
    description: "The netmask (e.g., 255.255.255.0) or prefix length (e.g., 24). Optional if address format implies it, but required for subnetcalc cli usage in this template context."
  },
  nodns: {
    type: bool,
    default: false,
    description: "Skip trying a reverse DNS lookup (-n)."
  },
  unique_local: {
    type: bool,
    default: false,
    description: "Replace first 48 bits with random IPv6 Unique Local prefix (-uniquelocal)."
  },
  unique_local_hq: {
    type: bool,
    default: false,
    description: "Use /dev/random for highest-quality random generation (-uniquelocalhq)."
  },
  no_color: {
    type: bool,
    default: false,
    description: "Turns colourised output off (-nocolour)."
  }
}
